static void drawSkin(int sx, int sy, int k)
{
	int f = (g_tick / SKIN_DELAY[k]) % SKIN_N[k];
	const unsigned char* d = &SKIN_PX[(SKIN_FIRST[k] + f) * 1024];
	for (int i = 0; i < 256; i++)
		if (d[i * 4 + 3]) putRect(sx + (i & 15), sy + (i >> 4), 1, 1, d[i * 4], d[i * 4 + 1], d[i * 4 + 2]);
}

static void drawTile(int sx, int sy, int v)
{
	if (v >= 2 && v - 2 < NSKIN) { drawSkin(sx, sy, v - 2); return; }
	putRect(sx, sy, T, T, 200, 76, 12);
	putRect(sx, sy, T, 1, 225, 157, 121);
	putRect(sx, sy + T - 1, T, 1, 90, 34, 5);
	putRect(sx + T - 1, sy, 1, T, 90, 34, 5);
	putRect(sx + 7, sy + 4, 1, 8, 140, 53, 8);
}

static void drawCloud(int x, int y)
{
	putRect(x + 8, y, 24, 8, 255, 255, 255);
	putRect(x, y + 8, 48, 10, 255, 255, 255);
	putRect(x + 6, y + 18, 36, 4, 235, 245, 255);
}

static void drawSkinScaled(int sx, int sy, int k, int dw, int dh, int flip)
{
	int f = (g_tick / SKIN_DELAY[k]) % SKIN_N[k];
	const unsigned char* d = &SKIN_PX[(SKIN_FIRST[k] + f) * 1024];
	for (int j = 0; j < dh; j++) {
		int syy = j * 16 / dh;
		for (int i = 0; i < dw; i++) {
			int sxx = i * 16 / dw;
			if (flip) sxx = 15 - sxx;
			const unsigned char* q = &d[(syy * 16 + sxx) * 4];
			if (q[3]) putRect(sx + i, sy + j, 1, 1, q[0], q[1], q[2]);
		}
	}
}

static void eRect(int sx, int sy, int sc, int a, int b, int w, int h, u8 r, u8 g, u8 bl)
{
	int x0 = a * sc / 100, y0 = b * sc / 100;
	int ww = (a + w) * sc / 100 - x0, hh = (b + h) * sc / 100 - y0;
	if (ww < 1) ww = 1;
	if (hh < 1) hh = 1;
	putRect(sx + x0, sy + y0, ww, hh, r, g, bl);
}

static void drawEnemy(int sx, int sy, const Enemy* e)
{
	int sc = e->sc;
	if (e->sk >= 0 && e->sk < NSKIN) {
		int cut = e->squash ? e->h * 6 / 10 : 0;
		drawSkinScaled(sx, sy + cut, e->sk, e->w, e->h - cut, 0);
		return;
	}
	if (e->squash) {
		eRect(sx, sy, sc, 0, 10, 14, 4, 160, 82, 45);
		eRect(sx, sy, sc, 0, 12, 14, 2, 60, 30, 10);
	} else {
		eRect(sx, sy, sc, 0, 0, 14, 10, 160, 82, 45);
		eRect(sx, sy, sc, 0, 10, 5, 4, 60, 30, 10);
		eRect(sx, sy, sc, 9, 10, 5, 4, 60, 30, 10);
		eRect(sx, sy, sc, 3, 4, 3, 4, 255, 255, 255);
		eRect(sx, sy, sc, 8, 4, 3, 4, 255, 255, 255);
		int o = e->dir > 0 ? 2 : 0;
		eRect(sx, sy, sc, 3 + o, 5, 1, 2, 0, 0, 0);
		eRect(sx, sy, sc, 8 + o, 5, 1, 2, 0, 0, 0);
	}
}

static void drawObjects(int camx)
{
	for (int i = 0; i < g_nc; i++) {
		if (g_coin[i].got) continue;
		int sx = g_coin[i].c * T - camx, sy = g_coin[i].r * T;
		int cw = coinW(g_coin[i].sc), ox = sx + (T - cw) / 2, oy = sy + T - cw;
		if (g_coin[i].sk >= 0 && g_coin[i].sk < NSKIN) { drawSkinScaled(ox, oy, g_coin[i].sk, cw, cw, 0); continue; }
		eRect(ox, oy, g_coin[i].sc, 4, 2, 8, 12, 255, 215, 0);
		eRect(ox, oy, g_coin[i].sc, 3, 4, 10, 8, 255, 215, 0);
		eRect(ox, oy, g_coin[i].sc, 7, 4, 2, 8, 255, 245, 150);
	}
	for (int i = 0; i < g_ne; i++) {
		Enemy* e = &g_en[i];
		if (!e->alive) continue;
		int sx = (int)e->x - camx, sy = (int)e->y;
		if (sx + e->w < 0 || sx > SW) continue;
		drawEnemy(sx, sy, e);
	}
}

static void drawShots(int camx)
{
	for (int i = 0; i < g_ns; i++) {
		Shot* s = &g_shot[i];
		if (!s->alive) continue;
		int x = (int)s->x - camx, y = (int)s->y;
		if (x < -16 || x > SW + 16) continue;
		if (s->kind == 0) {
			putRect(x, y, 4, 4, 40, 30, 10);
			putRect(x + 1, y + 1, 2, 2, 255, 220, 90);
		} else {
			int ph = (g_tick / 4) & 1;
			putRect(x + (ph ? 0 : 2), y, 6, 4, 190, 190, 200);
			putRect(x + (ph ? 2 : 4), y + 3, 2, 6, 120, 70, 20);
		}
	}
}

static void drawNum(int x, int y, int n, int sc)
{
	char s[12];
	sprintf(s, "%d", n);
	for (char* q = s; *q; q++) {
		unsigned short f = FONT[*q - '0'];
		for (int i = 0; i < 15; i++)
			if ((f >> (14 - i)) & 1) putRect(x + (i % 3) * sc, y + (i / 3) * sc, sc, sc, 255, 255, 255);
		x += 4 * sc;
	}
}

static void drawHud(void)
{
	putRect(0, 0, 112, 22, 20, 20, 30);
	putRect(8, 6, 10, 10, 255, 215, 0);
	putRect(11, 8, 2, 6, 255, 245, 150);
	drawNum(24, 6, g_got, 2);
	putRect(62, 6, 10, 10, 255, 205, 150);
	putRect(62, 6, 10, 4, 220, 30, 30);
	drawNum(78, 6, g_lives, 2);
}

static unsigned short glyph(char ch)
{
	if (ch >= '0' && ch <= '9') return FONT[ch - '0'];
	for (unsigned i = 0; i < sizeof(LETT) / sizeof(LETT[0]); i++)
		if (LETT[i].ch == ch) return LETT[i].f;
	return 0;
}

static void drawText(int x, int y, const char* t, int sc)
{
	for (; *t; t++) {
		unsigned short f = glyph(*t);
		for (int i = 0; i < 15; i++)
			if ((f >> (14 - i)) & 1) putRect(x + (i % 3) * sc, y + (i / 3) * sc, sc, sc, 255, 255, 255);
		x += 4 * sc;
	}
}

static void drawWin(void)
{
	putRect(70, 70, 260, 100, 20, 20, 30);
	putRect(70, 70, 260, 3, 255, 215, 0);
	putRect(70, 167, 260, 3, 255, 215, 0);
	drawText(134, 88, "COMPLETADO!", 3);
	drawText(148, 132, "A: REINTENTAR", 2);
}

static int sq_(int v) { return v * PS / 100; }

static void pRect(int sx, int sy, int a, int b, int w, int h, u8 r, u8 g, u8 bl)
{
	int x0 = sq_(a), y0 = sq_(b);
	int ww = sq_(a + w) - x0, hh = sq_(b + h) - y0;
	if (ww < 1) ww = 1;
	if (hh < 1) hh = 1;
	putRect(sx + x0, sy + y0, ww, hh, r, g, bl);
}

static void pLine(int sx, int sy, int x0, int y0, int x1, int y1, int th, u8 r, u8 g, u8 b)
{
	int t = sq_(th);
	if (t < 1) t = 1;
	putLine(sx + sq_(x0), sy + sq_(y0), sx + sq_(x1), sy + sq_(y1), t, r, g, b);
}

static void drawPlayer(int sx, int sy, const Player* p)
{
	const u8 cr = 20, cg = 20, cb = 20;
	if (PSKIN >= 0 && PSKIN < NSKIN) { drawSkinScaled(sx, sy, PSKIN, PW, PH, p->facing < 0); return; }
	float swing = 0.0f;
	if (p->onGround) swing = sinf(p->phase) * 5.0f;
	int sw = (int)swing, sa = (int)(swing * 0.8f);

	if (p->onGround) {
		pLine(sx, sy, 5, 16, 5 + sw, 23, 2, cr, cg, cb);
		pLine(sx, sy, 5, 16, 5 - sw, 23, 2, cr, cg, cb);
	} else {
		pLine(sx, sy, 5, 16, 1, 22, 2, cr, cg, cb);
		pLine(sx, sy, 5, 16, 9, 22, 2, cr, cg, cb);
	}

	pRect(sx, sy, 4, 8, 2, 9, cr, cg, cb);

	if (p->onGround) {
		pLine(sx, sy, 5, 10, 5 - sa, 16, 2, cr, cg, cb);
		pLine(sx, sy, 5, 10, 5 + sa, 16, 2, cr, cg, cb);
	} else {
		pLine(sx, sy, 5, 10, 0, 5, 2, cr, cg, cb);
		pLine(sx, sy, 5, 10, 10, 5, 2, cr, cg, cb);
	}

	pRect(sx, sy, 1, 0, 8, 8, 255, 205, 150);
	pRect(sx, sy, 1, 0, 8, 3, 220, 30, 30);
	if (p->facing > 0) {
		pRect(sx, sy, 7, 4, 1, 2, 0, 0, 0);
		pRect(sx, sy, 8, 2, 3, 2, 220, 30, 30);
	} else {
		pRect(sx, sy, 2, 4, 1, 2, 0, 0, 0);
		pRect(sx, sy, -1, 2, 3, 2, 220, 30, 30);
	}
}

static void addCoin(int c, int r, int sk, int sc)
{
	if (g_nc < MAXC) { g_coin[g_nc].c = c; g_coin[g_nc].r = r; g_coin[g_nc].got = 0; g_coin[g_nc].sk = sk; g_coin[g_nc].sc = sc; g_nc++; }
}

static void addEnemy(int c, int r, int dir, int beh, int sk, int sc, int st)
{
	if (g_ne < MAXE) {
		Enemy* e = &g_en[g_ne++];
		e->sc = sc;
		e->w = EW * sc / 100; if (e->w < 4) e->w = 4;
		e->h = EH * sc / 100; if (e->h < 4) e->h = 4;
		e->x = c * T + (T - e->w) / 2; e->y = (r + 1) * T - e->h; e->vx = 0; e->vy = 0;
		e->dir = dir; e->alive = 1; e->squash = 0; e->st = st;
		e->beh = beh; e->sk = sk; e->on = 0; e->jt = 30 + (c * 7) % 40;
		e->gt = 40 + (c * 7) % 60;
	}
}

