static int solidAt(int tx, int ty)
{
	if (tx < 0 || tx >= COLS) return 1;
	if (ty < 0 || ty >= ROWS) return 0;
	return g_map[ty][tx];
}

static void resetPlayer(void)
{
	g_player.x = g_startC * T;
	g_player.y = (g_startR + 1) * T - PH;
	g_player.vx = 0;
	g_player.vy = 0;
	g_player.onGround = 1;
	g_player.facing = 1;
	g_player.phase = 0;
	g_player.gp = -1;
	g_player.tr = 0;
	g_inv = 90;
	g_ns = 0;
}

static int physAt(int tx, int ty)
{
	if (tx < 0 || tx >= COLS || ty < 0 || ty >= ROWS || !g_map[ty][tx]) return -1;
	return TILE_PHYS[g_map[ty][tx]];
}

static int solidPl(int tx, int ty)
{
	if (tx < 0 || tx >= COLS) return 1;
	int q = physAt(tx, ty);
	return (q == 0 || q == 3 || q == 4);
}

static int zoneAt(const Player* p)
{
	int z = 0;
	int l = (int)floorf(p->x / T), r = (int)floorf((p->x + PW - 0.01f) / T);
	int t = (int)floorf(p->y / T), b = (int)floorf((p->y + PH - 1) / T);
	for (int ty = t; ty <= b; ty++)
		for (int tx = l; tx <= r; tx++) {
			int q = physAt(tx, ty);
			if (q == 1) z |= 1;
			else if (q == 2) z |= 2;
		}
	return z;
}

static float approach(float v, float target, float step)
{
	if (v < target) { v += step; if (v > target) v = target; }
	else if (v > target) { v -= step; if (v < target) v = target; }
	return v;
}

static void spawnShot(Enemy* e, int kind)
{
	if (g_ns >= MAXS) return;
	Shot* s = &g_shot[g_ns++];
	s->kind = kind;
	s->alive = 1;
	if (kind == 0) {
		s->x = e->x + e->w / 2 - 2; s->y = e->y + e->h / 2 - 2;
		s->vx = e->dir * 2.2f; s->vy = 0; s->life = 60;
	} else {
		s->x = e->x + e->w / 2 - 2; s->y = e->y - 6;
		s->vx = e->dir * 1.7f; s->vy = -4.2f; s->life = 150;
	}
}

static void updateShots(void)
{
	for (int i = 0; i < g_ns; i++) {
		Shot* s = &g_shot[i];
		if (!s->alive) continue;
		s->x += s->vx;
		if (s->kind == 1) {
			s->vy += GRAVITY;
			if (s->vy > MAX_FALL) s->vy = MAX_FALL;
			s->y += s->vy;
		}
		if (--s->life <= 0) { s->alive = 0; continue; }
		int cx = (int)floorf((s->x + 2) / T);
		int cy = (int)floorf((s->y + 2) / T);
		if (solidAt(cx, cy)) { s->alive = 0; continue; }
		if (s->x < -16 || s->x > COLS * T + 16 || s->y > SH + 40) s->alive = 0;
	}
	int n = 0;
	for (int i = 0; i < g_ns; i++)
		if (g_shot[i].alive) g_shot[n++] = g_shot[i];
	g_ns = n;
}

static void updatePlayer(Player* p, int dir, int run, int jumpPressed, int jumpHeld)
{
	int zn = zoneAt(p);
	float target = dir * (run ? RUN_SPEED : WALK_SPEED);
	float accel = p->onGround ? 0.30f : 0.18f;
	if (dir == 0) accel = p->onGround ? 0.40f : 0.05f;
	if (p->onGround && p->gp == 3) accel *= 0.12f;
	if (zn & 2) target *= 0.5f;
	p->vx = approach(p->vx, target, accel);
	if (dir != 0) p->facing = dir;

	if (jumpPressed && (p->onGround || (zn & 2))) {
		p->vy = -JUMP_SPEED * (p->onGround ? 1.0f : 0.6f);
		p->onGround = 0;
	}
	if (!jumpHeld && p->vy < -3.0f && !p->tr) p->vy = -3.0f;

	if (zn & 2) p->vy += GRAVITY * 0.3f; else p->vy += GRAVITY;
	if (zn & 2) { if (p->vy > 0.8f) p->vy = 0.8f; }
	else if (p->vy > MAX_FALL) p->vy = MAX_FALL;

	p->x += p->vx;
	{
		int top = (int)floorf(p->y / T);
		int bot = (int)floorf((p->y + PH - 1) / T);
		if (p->vx > 0) {
			int tx = (int)floorf((p->x + PW - 0.01f) / T);
			for (int ty = top; ty <= bot; ty++) {
				if (solidPl(tx, ty)) { p->x = tx * T - PW; p->vx = 0; break; }
			}
		} else if (p->vx < 0) {
			int tx = (int)floorf(p->x / T);
			for (int ty = top; ty <= bot; ty++) {
				if (solidPl(tx, ty)) { p->x = (tx + 1) * T; p->vx = 0; break; }
			}
		}
	}

	p->y += p->vy;
	p->onGround = 0;
	p->gp = -1;
	{
		int l = (int)floorf(p->x / T);
		int r = (int)floorf((p->x + PW - 0.01f) / T);
		if (p->vy >= 0) {
			int ty = (int)floorf((p->y + PH) / T);
			for (int tx = l; tx <= r; tx++) {
				if (solidPl(tx, ty)) {
					p->y = ty * T - PH;
					int gq = physAt(tx, ty);
					if (gq == 4) { p->vy = -JUMP_SPEED * TRAMP_MUL; p->tr = 1; }
					else { p->vy = 0; p->onGround = 1; p->gp = gq; }
					break;
				}
			}
		} else {
			int ty = (int)floorf(p->y / T);
			for (int tx = l; tx <= r; tx++) {
				if (solidPl(tx, ty)) {
					p->y = (ty + 1) * T;
					p->vy = 0;
					break;
				}
			}
		}
	}

	if (p->onGround && fabsf(p->vx) > 0.1f)
		p->phase += fabsf(p->vx) * 0.18f;
	else if (p->onGround)
		p->phase = 0;
	if (p->vy >= 0) p->tr = 0;
}

static void updateEnemy(Enemy* e)
{
	if (!e->alive) return;
	if (e->squash) { if (--e->squash == 0) e->alive = 0; return; }

	if (e->beh == 5) {
		e->x += e->dir * ENEMY_SPEED * 1.2f;
		int top = (int)floorf(e->y / T);
		int bot = (int)floorf((e->y + e->h - 1) / T);
		int tx = e->dir > 0 ? (int)floorf((e->x + e->w - 0.01f) / T) : (int)floorf(e->x / T);
		for (int ty = top; ty <= bot; ty++) {
			if (solidAt(tx, ty)) {
				e->x = e->dir > 0 ? tx * T - e->w : (tx + 1) * T;
				e->dir = -e->dir;
				break;
			}
		}
		if (e->x < 0) { e->x = 0; e->dir = 1; }
		if (e->x + e->w > COLS * T) { e->x = COLS * T - e->w; e->dir = -1; }
		return;
	}

	if (e->beh == 0 || e->beh == 3) {
		e->x += e->dir * ENEMY_SPEED;
		int top = (int)floorf(e->y / T);
		int bot = (int)floorf((e->y + e->h - 1) / T);
		int tx = e->dir > 0 ? (int)floorf((e->x + e->w - 0.01f) / T) : (int)floorf(e->x / T);
		for (int ty = top; ty <= bot; ty++) {
			if (solidAt(tx, ty)) {
				e->x = e->dir > 0 ? tx * T - e->w : (tx + 1) * T;
				e->dir = -e->dir;
				break;
			}
		}
	}

	if (e->beh == 2 && e->on && --e->jt <= 0) { e->vy = -4.5f; e->jt = 70; e->on = 0; }

	if ((e->beh == 3 || e->beh == 4) && --e->gt <= 0) {
		e->gt = (e->beh == 3) ? 70 : 100;
		float reach = (e->beh == 3) ? 120.0f : 170.0f;
		if (fabsf(g_player.x - e->x) < reach && fabsf(g_player.y - e->y) < 90.0f) {
			e->dir = (g_player.x < e->x) ? -1 : 1;
			spawnShot(e, (e->beh == 3) ? 0 : 1);
		}
	}

	e->vy += GRAVITY;
	if (e->vy > MAX_FALL) e->vy = MAX_FALL;
	e->y += e->vy;
	if (e->vy < 0) {
		int l = (int)floorf(e->x / T);
		int r = (int)floorf((e->x + e->w - 0.01f) / T);
		int ty = (int)floorf(e->y / T);
		for (int tx = l; tx <= r; tx++) {
			if (solidAt(tx, ty)) { e->y = (ty + 1) * T; e->vy = 0; break; }
		}
	}
	e->on = 0;
	{
		int l = (int)floorf(e->x / T);
		int r = (int)floorf((e->x + e->w - 0.01f) / T);
		int ty = (int)floorf((e->y + e->h) / T);
		for (int tx = l; tx <= r; tx++) {
			if (solidAt(tx, ty)) { e->y = ty * T - e->h; e->vy = 0; e->on = 1; break; }
		}
	}
	if (e->y > SH + 40) e->alive = 0;
}

static void resetLevel(void)
{
	g_lives = START_LIVES;
	g_got = 0;
	buildLevel();
	resetPlayer();
}

static void loseLife(int fell)
{
	g_lives--;
	if (g_lives <= 0) { g_deaths++; resetLevel(); return; }
	if (fell || !STAY_ON_HIT) resetPlayer();
	else { g_inv = 90; g_player.vy = -4.5f; g_player.onGround = 0; }
}

int main(int argc, char* argv[])
{
	gfxInitDefault();
	consoleInit(GFX_BOTTOM, NULL);

	printf("\x1b[1;1H=== Mi Juego 3DS ===");
	printf("\x1b[4;1HCruceta / Stick : caminar");
	printf("\x1b[6;1HA               : saltar");
	printf("\x1b[8;1HB (mantener)    : correr");
	printf("\x1b[10;1HLlega a la bandera roja!");
	printf("\x1b[14;1HSTART          : salir");
	printf("\x1b[17;1HMetas: 0   Derrotas: 0   ");

	buildLevel();
	resetPlayer();

	int lastWins = 0, lastDeaths = 0, lastGot = -1, lastLives = -1;
	int won = 0;

	while (aptMainLoop())
	{
		hidScanInput();
		u32 held = hidKeysHeld();
		u32 down = hidKeysDown();
		g_tick++;

		if (down & KEY_START) break;

		if (won) {
			if (down & KEY_A) {
				won = 0;
				g_level = 0;
				resetLevel();
				printf("\x1b[12;1H								  ");
			}
		} else {
		circlePosition cp;
		hidCircleRead(&cp);

		int dir = 0;
		if ((held & KEY_DRIGHT) || cp.dx > 30) dir += 1;
		if ((held & KEY_DLEFT)  || cp.dx < -30) dir -= 1;
		int run = (held & KEY_B) ? 1 : 0;

		updatePlayer(&g_player, dir, run, (down & KEY_A) ? 1 : 0, (held & KEY_A) ? 1 : 0);

		for (int i = 0; i < g_ne; i++) updateEnemy(&g_en[i]);
		updateShots();
		if (g_inv > 0) g_inv--;

		for (int i = 0; i < g_ne; i++) {
			Enemy* e = &g_en[i];
			if (!e->alive || e->squash) continue;
			if (g_player.x < e->x + e->w && g_player.x + PW > e->x &&
				g_player.y < e->y + e->h && g_player.y + PH > e->y) {
				if (e->st && g_player.vy > 0 && g_player.y + PH - e->y < 12) {
					e->squash = 20;
					g_player.vy = -5.5f;
					g_player.onGround = 0;
				} else if (g_inv == 0) {
					loseLife(0);
					break;
				}
			}
		}

		for (int i = 0; i < g_ns; i++) {
			Shot* s = &g_shot[i];
			if (!s->alive) continue;
			int sw = (s->kind == 0) ? 5 : 8;
			if (g_player.x < s->x + sw && g_player.x + PW > s->x &&
				g_player.y < s->y + 8 && g_player.y + PH > s->y) {
				s->alive = 0;
				if (g_inv == 0) { loseLife(0); break; }
			}
		}

		if (g_inv == 0 && (zoneAt(&g_player) & 1)) loseLife(0);

		for (int i = 0; i < g_nc; i++) {
			Coin* k = &g_coin[i];
			int cw = coinW(k->sc), ox = k->c * T + (T - cw) / 2, oy = k->r * T + T - cw;
			if (!k->got && g_player.x + PW > ox + 4 * cw / 16 && g_player.x < ox + 12 * cw / 16 &&
				g_player.y + PH > oy + 2 * cw / 16 && g_player.y < oy + 14 * cw / 16) {
				k->got = 1;
				g_got++;
			}
		}

		if (g_player.y > SH + 40) loseLife(1);

		if (g_player.x > g_goal * T) {
			g_wins++;
			if (g_level < NLEV - 1) { g_level++; resetLevel(); }
			else {
			won = 1;
			printf("\x1b[12;1HNivel completado!  A: reintentar");
			}
		}
		}

		if (g_wins != lastWins || g_deaths != lastDeaths || g_got != lastGot || g_lives != lastLives) {
			printf("\x1b[15;1HMonedas: %d   Vidas: %d   ", g_got, g_lives);
			printf("\x1b[17;1HMetas: %d   Derrotas: %d   ", g_wins, g_deaths);
			lastWins = g_wins; lastDeaths = g_deaths; lastGot = g_got; lastLives = g_lives;
		}

		float cam = g_player.x + PW / 2 - SW / 2;
		if (cam < 0) cam = 0;
		if (cam > COLS * T - SW) cam = COLS * T - SW;
		int camx = (int)cam;

		fb = gfxGetFramebuffer(GFX_TOP, GFX_LEFT, NULL, NULL);

		putRect(0, 0, SW, SH, g_skyr, g_skyg, g_skyb);
		if (SKY_IMG[g_level])
			for (int j = 0; j < 60; j++)
				for (int i = 0; i < 100; i++) {
					const unsigned char* q = &SKY_IMG[g_level][(j * 100 + i) * 3];
					putRect(i * 4, j * 4, 4, 4, q[0], q[1], q[2]);
				}

		for (int i = 0; !SKY_IMG[g_level] && i < 8; i++) {
			int wx = 60 + i * 330;
			drawCloud(wx - camx / 2, 20 + (i % 3) * 22);
		}

		int firstCol = camx / T;
		int lastCol = (camx + SW) / T;
		if (lastCol >= COLS) lastCol = COLS - 1;
		for (int ty = 0; ty < ROWS; ty++) {
			for (int tx = firstCol; tx <= lastCol; tx++) {
				if (g_map[ty][tx]) drawTile(tx * T - camx, ty * T, g_map[ty][tx]);
			}
		}

		{
			drawObjects(camx);
			drawShots(camx);
			int px = g_goal * T - camx;
			putRect(px + 6, 4 * T, 4, 9 * T, 220, 220, 220);
			putRect(px + 10, 4 * T + 2, 20, 12, 220, 30, 30);
			putRect(px + 4, 4 * T - 4, 8, 4, 255, 215, 0);
		}

		if (!(g_inv > 0 && ((g_inv >> 2) & 1))) drawPlayer((int)(g_player.x - camx), (int)g_player.y, &g_player);
		drawHud();

		if (won) drawWin();

		gfxFlushBuffers();
		gfxSwapBuffers();
		gspWaitForVBlank();
	}

	gfxExit();
	return 0;
}
